const STATE = require('STATE')
const statedb = STATE(__filename)
const { sdb, get } = statedb(fallback_module)

const btc_usd_rate = require('btc_usd_rate')

module.exports = btc_input_card

async function btc_input_card (opts = {}) {
  const { id, sdb } = await get(opts.sid)
  const { drive } = sdb
  
  const on = {
    style: inject,
    data: ondata,
  }

  const el = document.createElement('div')
  const shadow = el.attachShadow({ mode: 'closed' })

  let balanceOverride = null

  // Shared mutable state — accessed by both the public API and ondata handlers
  let _amount = 0
  let _balance = 0
  let _currency = 'BTC'
  let _showError = null   // set once ondata renders the UI

  shadow.innerHTML = `
    <div class="btc-card"></div>
    <style></style>
  `
  const style = shadow.querySelector('style')
  const container = shadow.querySelector('.btc-card')

  // ---- Public API — defined HERE (before sdb.watch) so callers never get undefined ----
  el.getAmount = function () { return _amount }

  el.setAmount = function (btcVal) {
    _amount = parseFloat(btcVal) || 0
    // If ondata has already rendered the UI, update it directly
    const input = container.querySelector('.amount-input')
    if (input) {
      input.value = _currency === 'BTC' ? _amount : (_amount * 0) // USD path rare
      input.dataset.cleared = '0'
    }
    const usdText = container.querySelector('.usd-text strong')
    if (usdText) usdText.textContent = `USD 0.00` // refreshed by rate call
    if (_showError) {
      _amount > _balance ? _showError('Insufficient balance, please add funds to your account') : _showError('')
    }
  }

  el.updateBalance = function (newBalance) {
    balanceOverride = newBalance
    _balance = newBalance
    // Update balance display if ondata has already rendered the UI
    const balanceEl = container.querySelector('.balance')
    if (balanceEl) {
      balanceEl.innerHTML = `Balance ${_balance} BTC <span style="display:inline-flex; align-items:center; justify-content:center; width:14px; height:14px; border-radius:50%; background:#000; color:#fff; font-size:10px; font-weight:bold; margin-left:4px; cursor:pointer;">+</span>`
    }
    if (_showError) {
      _amount > _balance ? _showError('Insufficient balance, please add funds to your account') : _showError('')
    }
  }
  // ---- End public API ----

  await sdb.watch(onbatch)

  return el

  function fail(data, type) {
    throw new Error('invalid message', { cause: { data, type } })
  }

  async function onbatch (batch) {
    for (const { type, paths } of batch) {
      const data = await Promise.all(
        paths.map(path => drive.get(path).then(file => file.raw))
      )
      const func = on[type] || fail
      await func(data, type)
    }
  }

  function inject (data) {
    style.textContent = data[0]
  }

  async function ondata (data) {
    let {
      currency = "BTC",
      amount = 0,
      usdValue: usd_value = 0,
      balance = 0, 
      show_balance = true
    } = data[0]

    if (balanceOverride !== null) {
      balance = balanceOverride
    }

    // Keep shared state in sync
    _amount = amount
    _balance = balance
    _currency = currency

    let EXCHANGE_RATE = 0

    container.innerHTML = `
      <div class="header">
        <span class="toggle ${currency === 'BTC' ? 'active' : ''}" data-currency="BTC">BTC</span>
        <span class="toggle ${currency === 'USD' ? 'active' : ''}" data-currency="USD">USD</span>
      </div>

      <div class="main-area"> 
        <div class="amount-row">
          <input type="number" min="0" step="0.0001" value="0" class="amount-input" data-cleared="0" />
          <div class="actions">
            <button class="close-btn">✕</button>
          </div>
        </div>
        <div class="error"></div>
        ${show_balance ? `<div class="balance">Balance ${_balance} BTC <span style="display:inline-flex; align-items:center; justify-content:center; width:14px; height:14px; border-radius:50%; background:#000; color:#fff; font-size:10px; font-weight:bold; margin-left:4px; cursor:pointer;">+</span></div>` : ""}
        <div class="usd-text">
          You are sending 
          <strong>USD ${(amount * EXCHANGE_RATE).toFixed(2)}</strong>
        </div>
      </div>
    `

    const amount_input = container.querySelector('.amount-input')
    const btc_toggle = container.querySelector('[data-currency="BTC"]')
    const usd_toggle = container.querySelector('[data-currency="USD"]')
    const usd_text = container.querySelector('.usd-text strong')
    const close_btn = container.querySelector('.close-btn')
    const error_div = container.querySelector('.error')
    const toggles = container.querySelectorAll('.toggle')

    // Wipe input on first click
    amount_input.onclick = () => {
      if (amount_input.dataset.cleared === "0") {
        amount_input.value = ""
        amount_input.dataset.cleared = "1"
      }
    }
    
    function showError(msg) {
      if (msg) {
        error_div.innerHTML = `<div class="divider"></div>${msg}`
      } else {
        error_div.innerHTML = ""
      }
    }

    function update_values(newAmountBTC) {
      amount = parseFloat(newAmountBTC) || 0
      usd_value = (amount * EXCHANGE_RATE).toFixed(2)
      if (amount > _balance) {
        showError("Insufficient balance, please add funds to your account")
      } else {
        showError("")
      }
    }

    function update_display(value, curr) {
      amount_input.value = value
      amount_input.dataset.cleared = "0" // reset wipe flag

      usd_text.textContent = curr === 'BTC'
        ? `USD ${usd_value}`
        : `${amount} BTC`

      toggles.forEach(t => t.classList.remove('active'))
      if (curr === 'BTC') {
        btc_toggle.classList.add('active')
      } else {
        usd_toggle.classList.add('active')
      }
    }

    function on_toggle_btc() {
      currency = 'BTC'
      update_display(amount, currency)
    }

    function on_toggle_usd() {
      currency = 'USD'
      update_display(usd_value, currency)
    }

    function on_close_click() {
      amount = 0
      usd_value = 0
      update_display(currency === 'BTC' ? amount : usd_value, currency)
      showError("")
    }

    // Keep shared state in sync on every input
    function on_amount_input() {
      let val = amount_input.value;

      if (val < 0) val = '';

      if (val === "" || isNaN(val)) {
        val = "0";
      }

      if (val.includes('.')) {
        let [int_part, dec_part] = val.split('.');
        if (currency === 'BTC') {
          int_part = int_part.slice(0, 5);
          dec_part = dec_part.slice(0, 8);
        } else {
          int_part = int_part.slice(0, 10);
          dec_part = dec_part.slice(0, 1);
        }
        val = int_part + (dec_part ? '.' + dec_part : '');
      } else {
        if (currency === 'BTC') {
          val = val.slice(0, 5);
        } else {
          val = val.slice(0, 10);
        }
      }

      if (currency === 'BTC') {
        amount = parseFloat(val) || 0;
        usd_value = (amount * EXCHANGE_RATE).toFixed(2);
      } else {
        usd_value = parseFloat(val) || 0;
        amount = +(usd_value / EXCHANGE_RATE).toFixed(8); 
      }

      _amount = amount  // keep shared state in sync

      if (amount > _balance) {
        showError("Insufficient balance, please add funds to your account");
      } else {
        showError("");
      }

      usd_text.textContent = currency === 'BTC'
        ? `USD ${usd_value}`
        : `${amount.toFixed(8)} BTC`;
    }

    // Wire _showError so the public updateBalance API can call it
    _showError = showError

    btc_toggle.onclick = on_toggle_btc
    usd_toggle.onclick = on_toggle_usd
    close_btn.onclick = on_close_click
    amount_input.oninput = on_amount_input

    // NOTE: el.getAmount / el.setAmount / el.updateBalance are defined ABOVE sdb.watch
    // so they are always available. No need to redefine them here.

    btc_usd_rate('btc', 'usd').then(rate => {
      EXCHANGE_RATE = rate
      on_amount_input()
    }).catch(() => { /* btc/usd rate unavailable */ })
  }
}

function fallback_module () {
  return {
    api: fallback_instance,
  }
  function fallback_instance (opts) {
    if (!opts) opts = {}
    if (!opts.value) opts.value = {}

    return {
      drive: {
        'style/': {
          'style.css': {
            '$ref': 'btc_input_card.css'
          }
        },
        'data/': {
          'opts.json': {
            raw: opts || {}
          },
        }
      }
    }
  }
}
